// Written with the help of Claude
// AI Usage: generated by Claude Code.
// and by manual review of every case against the schema and EventsService.
//
// Unit tests for events: the CreateEventBody schema (FR-010) and EventsService.cancel (FR-011).
// They import the built code from dist/, because Node cannot run the decorators in src/ directly.
// Run with `npx nest build && node --test tests/unit/events.unit.test.ts`.
import assert from 'node:assert/strict';
import { beforeEach, describe, mock, test } from 'node:test';
import { CreateEventBody } from '../../dist/api/catalog/schemas/events.js';
import { EventsRepository } from '../../dist/core/catalog/repositories/events.repository.js';
import { OrganizationsRepository } from '../../dist/core/catalog/repositories/organizations.repository.js';
import { VenuesRepository } from '../../dist/core/catalog/repositories/venues.repository.js';
import { CategoriesService } from '../../dist/core/catalog/services/categories.service.js';
import { EventsService } from '../../dist/core/catalog/services/events.service.js';
import { DomainError } from '../../dist/core/common/domain-error.js';

const ownerOrganization = '7d2e4f6a-8b0c-4d1e-9f3a-5b7c9d1e3f01';
const otherOrganization = '7d2e4f6a-8b0c-4d1e-9f3a-5b7c9d1e3f02';
const eventId = '3f1c2a9e-8b4d-4e2a-9c71-5d0e6b7a8f10';
const startsAt = new Date(Date.now() + 7 * 24 * 3600 * 1000).toISOString();
const endsAt = new Date(Date.parse(startsAt) + 2 * 3600 * 1000).toISOString();

function validEventBody() {
  return {
    title: 'Film quiz night',
    description: 'Teams of up to four, questions on Ukrainian cinema.',
    categoryId: '2d8b4f6c-0e3a-4c5d-9f7b-9a4c6e8d0f03',
    venueId: '5a1c3e5f-7b9d-4f1a-8c3e-5f7a9b1d3e05',
    startsAt,
    endsAt,
  };
}

function storedEvent(overrides = {}) {
  return {
    id: eventId,
    title: 'Film quiz night',
    description: 'Teams of up to four.',
    category: { id: '2d8b4f6c-0e3a-4c5d-9f7b-9a4c6e8d0f03', name: 'Concerts' },
    venue: {
      id: '5a1c3e5f-7b9d-4f1a-8c3e-5f7a9b1d3e05',
      name: 'Natalka Park lawn',
      address: 'Naberezhno-Luhova St, Kyiv',
      location: { lat: 50.4825, lng: 30.5181 },
      organizationId: ownerOrganization,
    },
    startsAt,
    endsAt,
    source: 'organization',
    status: 'published',
    organizationId: ownerOrganization,
    ...overrides,
  };
}

class FakeEventsRepository extends EventsRepository {
  stored: ReturnType<typeof storedEvent> | undefined;
  findById = mock.fn(async (id: string) => (this.stored?.id === id ? this.stored : undefined));
  update = mock.fn(async (_id: string, changes: object) => ({ ...this.stored, ...changes }));
}

class FakeOrganizationsRepository extends OrganizationsRepository {}
class FakeVenuesRepository extends VenuesRepository {}

describe('FR-010: CreateEventBody requires every event field', () => {
  const requiredFields = ['title', 'description', 'categoryId', 'venueId', 'startsAt', 'endsAt'] as const;

  for (const field of requiredFields) {
    test(`An event body without ${field} is rejected with an error that points at ${field}`, () => {
      // Arrange
      const body: Partial<ReturnType<typeof validEventBody>> = validEventBody();
      delete body[field];

      // Act
      const result = CreateEventBody.safeParse(body);

      // Assert
      if (result.success) assert.fail('expected the body to be rejected');
      assert.deepEqual(
        result.error.issues.map((issue: { path: PropertyKey[] }) => issue.path),
        [[field]],
      );
    });
  }

  test('An event body with every field filled in is accepted', () => {
    // Arrange
    const body = validEventBody();

    // Act
    const result = CreateEventBody.safeParse(body);

    // Assert
    assert.equal(result.success, true);
    assert.deepEqual(result.data, body);
  });
});

describe('FR-011: EventsService.cancel', () => {
  let eventsRepository: FakeEventsRepository;
  let service: InstanceType<typeof EventsService>;

  beforeEach(() => {
    eventsRepository = new FakeEventsRepository();
    service = new EventsService(
      eventsRepository,
      new FakeOrganizationsRepository(),
      new FakeVenuesRepository(),
      new CategoriesService(undefined),
    );
  });

  test('The organization that posted an event can cancel it, and the event is saved as cancelled', async () => {
    // Arrange
    eventsRepository.stored = storedEvent();

    // Act
    const result = await service.cancel(ownerOrganization, eventId);

    // Assert
    assert.equal(eventsRepository.update.mock.callCount(), 1);
    assert.deepEqual(eventsRepository.update.mock.calls[0]?.arguments, [eventId, { status: 'cancelled' }]);
    assert.equal(result.status, 'cancelled');
  });

  test('Another organization cannot cancel the event and is told it does not exist', async () => {
    // Arrange
    eventsRepository.stored = storedEvent();

    // Act
    const cancelling = service.cancel(otherOrganization, eventId);

    // Assert
    await assert.rejects(cancelling, (error) => error instanceof DomainError && error.code === 'NOT_FOUND');
    assert.equal(eventsRepository.update.mock.callCount(), 0);
  });

  test('Cancelling an event that is already cancelled returns it unchanged without saving anything', async () => {
    // Arrange
    const cancelled = storedEvent({ status: 'cancelled' });
    eventsRepository.stored = cancelled;

    // Act
    const result = await service.cancel(ownerOrganization, eventId);

    // Assert
    assert.equal(result, cancelled);
    assert.equal(eventsRepository.update.mock.callCount(), 0);
  });
});
